#nullable enable // autogenerated

using MVZ2.Vanilla.Entities;
using PVZEngine.Definitions;
using PVZEngine.Entities;

namespace MVZ2.GameContent.Enemies
{
    /// <summary>
    /// 舞王僵尸的“状态行为”。
    /// 作用：决定舞王现在是“走路”还是“站着不动”。
    /// 注意它不负责跳舞和召唤，那些在 DancingZombie 里做。
    /// </summary>
    [AutoEntityBehaviourDefinition(VanillaEntityBehaviourNames.dancingZombie_State)]
    public class DancingZombie_StateBehaviour : EnemyStateBehaviour
    {
        // 构造函数：引擎创建这个行为时调用，名字交给父类就行。
        public DancingZombie_StateBehaviour(string nsp, string name) : base(nsp, name)
        {
        }

        /// <summary>
        /// 引擎每帧都会问：这只敌人“现在应该处于什么状态”？
        /// 我们只在父类的答案上做一点修改。
        /// </summary>
        protected override int GetActiveState(Entity enemy)
        {
            // 先拿到父类算好的默认状态
            var state = base.GetActiveState(enemy);

            // 只有当默认状态是“走路”时，我们才可能改它
            if (state == STATE_WALK)
            {
                // 有伴舞掉队太远 → 停下等它
                // （出场冲刺阶段不再强制站桩，舞王要能走。）
                if (DancingZombie.ShouldWaitForDancers(enemy))
                {
                    state = STATE_IDLE; // 改成“站着不动”
                }
            }
            return state;
        }
    }
}
